import '@mantine/dates/styles.css';
import '@mantine/notifications/styles.css';
import '@mantine/schedule/styles.css';

import dayjs from 'dayjs';
import { useId, useMemo, useState } from 'react';
import { Box, Code, Group, ScrollArea, Text, useModal } from '@mantine/core';
import { notifications } from '@mantine/notifications';
import { AgendaView, MonthView, WeekView, type ScheduleEventData } from '@mantine/schedule';
import { CalendarHeader } from './CalendarHeader';
import { CHANNELS } from './channels';
import { createInitialData } from './data';
import { PostEventBody, renderAgendaPost, renderPostEvent } from './PostEvent/PostEvent';
import { PostForm } from './PostForm';
import {
  canUnschedule,
  createPostEvent,
  createPostId,
  DATE_FORMAT,
  DATE_TIME_FORMAT,
  getPostsInRange,
  getRangeLabel,
  getVisibleRange,
  isPublished,
  isSeriesIssue,
  toPostJson,
  toUnscheduled,
  updateIssue,
  updatePost,
  updateSeries,
  withDefaultTime,
  type PostChange,
} from './posts';
import { SeriesScopeForm } from './SeriesScopeForm';
import { DRAFT_DRAG_TYPE, Sidebar } from './Sidebar/Sidebar';
import type {
  CalendarView,
  Channel,
  PostEvent,
  PostFormValues,
  PostTarget,
  SeriesScope,
  UnscheduledPost,
} from './types';
import classes from './ContentCalendar.module.css';

const NEW_POST_AUTHOR = 'You';

const formatWhen = (start: string) => dayjs(start).format('ddd, MMM D, HH:mm');

const notify = (title: string, message: string) => notifications.show({ title, message });

function getFormValues(target: PostTarget): PostFormValues {
  if (target.kind === 'event') {
    return {
      title: target.event.title,
      channel: target.event.payload!.channel,
      date: dayjs(target.event.start).format(DATE_TIME_FORMAT),
      status: target.event.payload!.status,
    };
  }

  if (target.kind === 'unscheduled') {
    return { title: target.post.title, channel: target.post.channel, date: null, status: 'draft' };
  }

  return { title: '', channel: null, date: target.date, status: 'draft' };
}

function getFormTitle(target: PostTarget) {
  if (target.kind === 'new') {
    return 'New post';
  }
  return target.kind === 'event' && isSeriesIssue(target.event)
    ? 'Edit newsletter issue'
    : 'Edit post';
}

export function ContentCalendar() {
  const [initialData] = useState(() => createInitialData());
  const [events, setEvents] = useState<PostEvent[]>(initialData.events);
  const [unscheduled, setUnscheduled] = useState<UnscheduledPost[]>(initialData.unscheduled);
  const [channels, setChannels] = useState<Channel[]>(CHANNELS.map((channel) => channel.value));
  const [view, setView] = useState<CalendarView>('month');
  const [date, setDate] = useState(() => dayjs().format(DATE_FORMAT));
  const [draggedEvent, setDraggedEvent] = useState<PostEvent | null>(null);

  const jsonLabelId = useId();
  const formModal = useModal({ closeOnClickOutside: false });
  const scopeModal = useModal({ closeOnClickOutside: false });

  const visibleEvents = useMemo(
    () =>
      events
        .filter((event) => channels.includes(event.payload!.channel))
        .map((event) => ({
          ...event,
          variant: isPublished(event) ? 'filled' : 'light',
        })) as PostEvent[],
    [events, channels]
  );

  const visibleDrafts = unscheduled.filter((post) => channels.includes(post.channel));
  const range = getVisibleRange(view, date);
  const postsJson = useMemo(
    () =>
      JSON.stringify(
        getPostsInRange(visibleEvents, getVisibleRange(view, date)).map(toPostJson),
        null,
        2
      ),
    [visibleEvents, view, date]
  );

  const navigate = (direction: 1 | -1) =>
    setDate((current) =>
      dayjs(current)
        .add(direction, view === 'week' ? 'week' : 'month')
        .format(DATE_FORMAT)
    );

  const askScope = (issue: PostEvent, change: PostChange, action: 'updated' | 'moved') => {
    const apply = (scope: SeriesScope) => {
      scopeModal.close();
      setEvents((current) =>
        scope === 'issue'
          ? updateIssue(current, issue, change)
          : updateSeries(current, issue, change)
      );
      notify(
        `${scope === 'issue' ? 'Issue' : 'Series'} ${action}`,
        `${change.title} · ${formatWhen(change.start)}`
      );
    };

    scopeModal.open({
      title: 'Change newsletter issue',
      children: <SeriesScopeForm issueTitle={issue.title} onSubmit={apply} />,
    });
  };

  const unscheduleEvent = (event: PostEvent, change?: { title: string; channel: Channel }) => {
    setEvents((current) => current.filter((item) => item.id !== event.id));
    setUnscheduled((current) => [toUnscheduled(event, change), ...current]);
    notify('Draft unscheduled', change?.title ?? event.title);
  };

  const savePost = (target: PostTarget, values: PostFormValues) => {
    const channel = values.channel!;
    const start = values.date ? dayjs(values.date).format(DATE_TIME_FORMAT) : null;

    if (target.kind === 'event') {
      const { event } = target;
      if (!start) {
        unscheduleEvent(event, { title: values.title, channel });
        return;
      }

      const change = { title: values.title, channel, status: values.status, start };
      if (isSeriesIssue(event)) {
        askScope(event, change, 'updated');
        return;
      }

      setEvents((current) => updatePost(current, event.id, change));
      notify('Post updated', `${values.title} · ${formatWhen(start)}`);
      return;
    }

    const id = target.kind === 'unscheduled' ? target.post.id : createPostId();
    const author = target.kind === 'unscheduled' ? target.post.author : NEW_POST_AUTHOR;

    if (!start) {
      const post = { id, title: values.title, channel, author };
      setUnscheduled((current) =>
        target.kind === 'unscheduled'
          ? current.map((item) => (item.id === id ? post : item))
          : [post, ...current]
      );
      notify(
        target.kind === 'new' ? 'Draft created' : 'Draft updated',
        `${values.title} · Unscheduled`
      );
      return;
    }

    setUnscheduled((current) => current.filter((item) => item.id !== id));
    setEvents((current) => [
      ...current,
      createPostEvent({ id, title: values.title, channel, author, status: values.status, start }),
    ]);
    notify(
      target.kind === 'new' ? 'Post created' : 'Draft scheduled',
      `${values.title} · ${formatWhen(start)}`
    );
  };

  const openEditor = (target: PostTarget) => {
    const isEvent = target.kind === 'event';

    formModal.open({
      title: getFormTitle(target),
      children: (
        <PostForm
          initialValues={getFormValues(target)}
          isNew={target.kind === 'new'}
          dateLocked={isEvent && isPublished(target.event)}
          dateRequired={isEvent && isSeriesIssue(target.event)}
          onSubmit={(values) => {
            formModal.close();
            savePost(target, values);
          }}
        />
      ),
    });
  };

  const openNewPost = (day: string | null) =>
    openEditor({ kind: 'new', date: day === null ? null : withDefaultTime(day) });

  const handleEventDrop = ({ event, newStart }: { event: ScheduleEventData; newStart: string }) => {
    const post = event as PostEvent;
    const change = {
      title: post.title,
      channel: post.payload!.channel,
      status: post.payload!.status,
      start: newStart,
    };

    if (isSeriesIssue(post)) {
      askScope(post, change, 'moved');
      return;
    }

    setEvents((current) => updatePost(current, post.id, change));
    notify('Post moved', `${post.title} · ${formatWhen(newStart)}`);
  };

  const handleDraftDrop = (dataTransfer: DataTransfer, dropDateTime: string) => {
    const post = unscheduled.find((item) => item.id === dataTransfer.getData(DRAFT_DRAG_TYPE));
    if (!post) {
      return;
    }

    const start = withDefaultTime(dropDateTime);
    setUnscheduled((current) => current.filter((item) => item.id !== post.id));
    setEvents((current) => [...current, createPostEvent({ ...post, status: 'draft', start })]);
    notify('Draft scheduled', `${post.title} · ${formatWhen(start)}`);
  };

  const handleUnscheduleDrop = (eventId: string) => {
    const event = events.find((item) => String(item.id) === eventId);
    if (event && canUnschedule(event)) {
      unscheduleEvent(event);
    }
  };

  const dragProps = {
    events: visibleEvents,
    withEventsDragAndDrop: true,
    canDragEvent: (event: ScheduleEventData) => !isPublished(event as PostEvent),
    onEventDrop: handleEventDrop,
    onEventDragStart: (event: ScheduleEventData) => setDraggedEvent(event as PostEvent),
    onEventDragEnd: () => setDraggedEvent(null),
    canDropExternalEvent: ({ dataTransfer }: { dataTransfer: DataTransfer }) =>
      dataTransfer.types.includes(DRAFT_DRAG_TYPE),
    onExternalEventDrop: handleDraftDrop,
    onEventClick: (event: ScheduleEventData) =>
      openEditor({ kind: 'event', event: event as PostEvent }),
    renderEventBody: PostEventBody,
    renderEvent: renderPostEvent,
  };

  return (
    <Group align="flex-start" wrap="nowrap" gap="lg" className={classes.root}>
      <Sidebar
        channels={channels}
        onChannelsChange={setChannels}
        drafts={visibleDrafts}
        onNewPost={() => openNewPost(null)}
        onDraftClick={(post) => openEditor({ kind: 'unscheduled', post })}
        acceptsCalendarDrop={draggedEvent !== null && canUnschedule(draggedEvent)}
        onCalendarDrop={handleUnscheduleDrop}
      />

      <Box className={classes.main}>
        <CalendarHeader
          label={getRangeLabel(view, date)}
          view={view}
          onViewChange={setView}
          onPrevious={() => navigate(-1)}
          onNext={() => navigate(1)}
          onToday={() => setDate(dayjs().format(DATE_FORMAT))}
        />

        {view === 'month' && (
          <MonthView
            {...dragProps}
            date={date}
            onDateChange={setDate}
            withHeader={false}
            maxEventsPerDay={3}
            onDayClick={(day) => openNewPost(day)}
          />
        )}

        {view === 'week' && (
          <WeekView
            {...dragProps}
            date={date}
            onDateChange={setDate}
            withHeader={false}
            withAllDaySlots={false}
            startTime="07:00:00"
            endTime="21:00:00"
            intervalMinutes={30}
            startScrollTime="08:00:00"
            scrollAreaProps={{ mah: 640 }}
            onTimeSlotClick={({ slotStart }) => openNewPost(slotStart)}
          />
        )}

        {view === 'agenda' && (
          <AgendaView
            rangeStart={range.from.format(DATE_FORMAT)}
            rangeEnd={range.to.format(DATE_FORMAT)}
            events={visibleEvents}
            renderEvent={renderAgendaPost}
            onEventClick={(event) => openEditor({ kind: 'event', event: event as PostEvent })}
            classNames={{ agendaViewHeader: classes.hidden }}
          />
        )}

        <Text size="sm" fw={500} mt="lg" mb="xs" id={jsonLabelId}>
          Posts in view
        </Text>
        <ScrollArea.Autosize mah={420} type="auto">
          <Code block aria-labelledby={jsonLabelId}>
            {postsJson}
          </Code>
        </ScrollArea.Autosize>
      </Box>
    </Group>
  );
}

import { Group } from '@mantine/core';
import { ScheduleHeader } from '@mantine/schedule';
import type { CalendarView } from './types';

const VIEWS: { value: CalendarView; label: string }[] = [
  { value: 'month', label: 'Month' },
  { value: 'week', label: 'Week' },
  { value: 'agenda', label: 'Agenda' },
];

interface CalendarHeaderProps {
  label: string;
  view: CalendarView;
  onViewChange: (view: CalendarView) => void;
  onPrevious: () => void;
  onNext: () => void;
  onToday: () => void;
}

export function CalendarHeader({
  label,
  view,
  onViewChange,
  onPrevious,
  onNext,
  onToday,
}: CalendarHeaderProps) {
  return (
    <ScheduleHeader>
      <ScheduleHeader.Previous onClick={onPrevious} />
      <ScheduleHeader.Control interactive={false} miw={170} aria-live="polite">
        {label}
      </ScheduleHeader.Control>
      <ScheduleHeader.Next onClick={onNext} />
      <ScheduleHeader.Today onClick={onToday} />
      <Group gap={0} ms="auto" role="group" aria-label="Calendar view" wrap="nowrap">
        {VIEWS.map((item) => (
          <ScheduleHeader.Control
            key={item.value}
            active={view === item.value}
            aria-pressed={view === item.value}
            onClick={() => onViewChange(item.value)}
          >
            {item.label}
          </ScheduleHeader.Control>
        ))}
      </Group>
    </ScheduleHeader>
  );
}

import { act, fireEvent, render, screen, userEvent, within } from '@test-utils';
import { Notifications, notifications } from '@mantine/notifications';
import { ContentCalendar } from './ContentCalendar';

// Thursday, October 29 2026: October posts before today are published, the newsletter goes
// out on Tuesdays (Oct 6, 13, 20, 27 published, Nov 3 onwards scheduled)
const NOW = new Date(2026, 9, 29, 12, 0, 0);

interface PostJson {
  id: string;
  title: string;
  channel: string;
  author: string;
  status: string;
  start: string;
  seriesId?: string;
}

function setup() {
  const user = userEvent.setup({ advanceTimers: jest.advanceTimersByTime });
  render(
    <>
      <Notifications />
      <ContentCalendar />
    </>
  );
  return user;
}

function getPosts(): PostJson[] {
  return JSON.parse(screen.getByLabelText('Posts in view').textContent!);
}

function findPost(title: string) {
  return getPosts().find((post) => post.title === title);
}

function getEvent(title: string) {
  return screen.getByRole('button', { name: new RegExp(`^${title},`) });
}

function getDrafts() {
  return screen.getByRole('region', { name: 'Unscheduled drafts' });
}

function createDataTransfer() {
  const data: Record<string, string> = {};
  return {
    dropEffect: 'none',
    effectAllowed: 'all',
    get types() {
      return Object.keys(data);
    },
    setData: (type: string, value: string) => {
      data[type] = value;
    },
    getData: (type: string) => data[type] ?? '',
    clearData: () => {},
  };
}

function drag(source: HTMLElement, target: HTMLElement) {
  const dataTransfer = createDataTransfer();
  act(() => {
    fireEvent.dragStart(source, { dataTransfer });
  });
  act(() => {
    fireEvent.dragOver(target, { dataTransfer });
  });
  act(() => {
    fireEvent.drop(target, { dataTransfer });
  });
  act(() => {
    fireEvent.dragEnd(source, { dataTransfer });
  });
}

async function saveForm(user: ReturnType<typeof userEvent.setup>, buttonName = 'Save changes') {
  await user.click(within(screen.getByRole('dialog')).getByRole('button', { name: buttonName }));
}

async function replaceTitle(user: ReturnType<typeof userEvent.setup>, title: string) {
  const field = within(screen.getByRole('dialog')).getByRole('textbox', { name: 'Title' });
  await user.clear(field);
  await user.type(field, title);
}

async function chooseScope(user: ReturnType<typeof userEvent.setup>, scope: string) {
  const dialog = screen.getByRole('dialog', { name: 'Change newsletter issue' });
  await user.click(within(dialog).getByRole('radio', { name: scope }));
  await user.click(within(dialog).getByRole('button', { name: 'Apply' }));
}

beforeAll(() => {
  // jsdom has no scrolling; the week view scrolls its grid to startScrollTime
  Element.prototype.scrollTo = () => {};
});

beforeEach(() => {
  jest.useFakeTimers({ now: NOW, advanceTimers: true });
});

afterEach(() => {
  act(() => notifications.clean());
  jest.useRealTimers();
});

describe('ContentCalendar', () => {
  describe('calendar', () => {
    it('opens on the current month', () => {
      setup();
      expect(screen.getByText('October 2026')).toBeInTheDocument();
    });

    it('shows the title, channel and status of each post', () => {
      setup();
      expect(getEvent('Q4 product roadmap')).toHaveAccessibleName(
        'Q4 product roadmap, Blog, Published'
      );
    });

    it('moves to the next month with the next button', async () => {
      const user = setup();
      await user.click(screen.getByRole('button', { name: 'Next' }));
      expect(screen.getByText('November 2026')).toBeInTheDocument();
    });

    it('shows the week range in the week view', async () => {
      const user = setup();
      await user.click(screen.getByRole('button', { name: 'Week' }));
      expect(screen.getByText('Oct 26 – Nov 1, 2026')).toBeInTheDocument();
    });

    it('returns to the current month with the today button', async () => {
      const user = setup();
      await user.click(screen.getByRole('button', { name: 'Next' }));
      await user.click(screen.getByRole('button', { name: 'Today' }));
      expect(screen.getByText('October 2026')).toBeInTheDocument();
    });

    it('lists the posts of the month in the agenda view', async () => {
      const user = setup();
      await user.click(screen.getByRole('button', { name: 'Agenda' }));
      expect(
        screen.getByRole('button', { name: 'Conference recap, LinkedIn, Published' })
      ).toBeInTheDocument();
    });

    it('does not let published posts be dragged', () => {
      setup();
      expect(getEvent('Q4 product roadmap')).toHaveAttribute('draggable', 'false');
    });

    it('lets scheduled posts be dragged', async () => {
      const user = setup();
      await user.click(screen.getByRole('button', { name: 'Next' }));
      expect(getEvent('Release notes 4.2')).toHaveAttribute('draggable', 'true');
    });
  });

  describe('posts of the visible range', () => {
    it('shows the posts of the visible range as JSON', () => {
      setup();
      expect(findPost('Q4 product roadmap')).toEqual({
        id: 'post-1',
        title: 'Q4 product roadmap',
        channel: 'blog',
        author: 'Maya Chen',
        status: 'published',
        start: '2026-10-02 09:00:00',
      });
    });

    it('includes newsletter issues generated by the series', () => {
      setup();
      expect(getPosts().find((post) => post.start === '2026-11-03 10:00:00')).toMatchObject({
        title: 'Weekly newsletter',
        seriesId: 'newsletter',
        status: 'scheduled',
      });
    });

    it('leaves out posts after the visible range', () => {
      setup();
      expect(findPost('Security practices we follow')).toBeUndefined();
    });

    it('updates the JSON when the range changes', async () => {
      const user = setup();
      await user.click(screen.getByRole('button', { name: 'Next' }));
      expect(findPost('Security practices we follow')).toMatchObject({ status: 'draft' });
    });
  });

  describe('sidebar', () => {
    it('lists the unscheduled drafts', () => {
      setup();
      expect(within(getDrafts()).getAllByRole('button')).toHaveLength(6);
    });

    it('hides posts of unchecked channels from the calendar', async () => {
      const user = setup();
      await user.click(screen.getByRole('checkbox', { name: 'Blog' }));
      expect(
        screen.queryByRole('button', { name: /^Q4 product roadmap,/ })
      ).not.toBeInTheDocument();
    });

    it('hides posts of unchecked channels from the JSON', async () => {
      const user = setup();
      await user.click(screen.getByRole('checkbox', { name: 'Blog' }));
      expect(getPosts().some((post) => post.channel === 'blog')).toBe(false);
    });

    it('hides drafts of unchecked channels', async () => {
      const user = setup();
      await user.click(screen.getByRole('checkbox', { name: 'Instagram' }));
      expect(within(getDrafts()).queryByText('Customer quote cards')).not.toBeInTheDocument();
    });

    it('keeps posts of several checked channels', async () => {
      const user = setup();
      await user.click(screen.getByRole('checkbox', { name: 'Instagram' }));
      await user.click(screen.getByRole('checkbox', { name: 'Newsletter' }));
      expect(new Set(getPosts().map((post) => post.channel))).toEqual(
        new Set(['blog', 'linkedin'])
      );
    });
  });

  describe('post form', () => {
    it('opens the post with its values when it is clicked', async () => {
      const user = setup();
      await user.click(getEvent('Conference recap'));
      const dialog = screen.getByRole('dialog', { name: 'Edit post' });
      expect(within(dialog).getByRole('textbox', { name: 'Title' })).toHaveValue(
        'Conference recap'
      );
    });

    it('saves the edited title', async () => {
      const user = setup();
      await user.click(screen.getByRole('button', { name: 'Next' }));
      await user.click(getEvent('Release notes 4.2'));
      await replaceTitle(user, 'Release notes 4.2.1');
      await saveForm(user);
      expect(findPost('Release notes 4.2.1')).toMatchObject({
        id: 'post-12',
        start: '2026-11-02 09:00:00',
      });
    });

    it('saves the edited status', async () => {
      const user = setup();
      await user.click(screen.getByRole('button', { name: 'Next' }));
      await user.click(getEvent('Release notes 4.2'));
      await user.click(within(screen.getByRole('dialog')).getByRole('radio', { name: 'Draft' }));
      await saveForm(user);
      expect(findPost('Release notes 4.2')).toMatchObject({ status: 'draft' });
    });

    it('shows a notification after a post is saved', async () => {
      const user = setup();
      await user.click(screen.getByRole('button', { name: 'Next' }));
      await user.click(getEvent('Release notes 4.2'));
      await saveForm(user);
      expect(screen.getByText('Post updated')).toBeInTheDocument();
    });

    it('does not let the date of a published post change', async () => {
      const user = setup();
      await user.click(getEvent('Conference recap'));
      expect(screen.getByText('Published posts cannot be moved')).toBeInTheDocument();
    });

    it('opens an empty form with New post', async () => {
      const user = setup();
      await user.click(screen.getByRole('button', { name: 'New post' }));
      const dialog = screen.getByRole('dialog', { name: 'New post' });
      expect(within(dialog).getByRole('textbox', { name: 'Title' })).toHaveValue('');
    });

    it('requires a title', async () => {
