import dayjs from 'dayjs';
import type { CSSProperties } from 'react';
import {
  IconArticle,
  IconBrandInstagram,
  IconBrandLinkedin,
  IconCheck,
  IconMail,
  type Icon,
} from '@tabler/icons-react';
import { Group, Text, UnstyledButton } from '@mantine/core';
import type { ScheduleEventData } from '@mantine/schedule';
import { CHANNEL_LABELS, STATUS_LABELS } from '../channels';
import type { Channel, PostPayload } from '../types';
import classes from './PostEvent.module.css';

const CHANNEL_ICONS: Record<Channel, Icon> = {
  blog: IconArticle,
  newsletter: IconMail,
  linkedin: IconBrandLinkedin,
  instagram: IconBrandInstagram,
};

type RootProps = Record<string, any>;

function getPayload(event: ScheduleEventData) {
  return event.payload as PostPayload;
}

function getAccessibleName(event: ScheduleEventData) {
  const { channel, status } = getPayload(event);
  return `${event.title}, ${CHANNEL_LABELS[channel]}, ${STATUS_LABELS[status]}`;
}

export function PostEventBody(event: ScheduleEventData) {
  const { channel, status } = getPayload(event);
  const ChannelIcon = CHANNEL_ICONS[channel];

  return (
    <div className={classes.body}>
      <span className={classes.title}>
        <ChannelIcon size={12} className={classes.icon} />
        {status === 'published' && <IconCheck size={12} stroke={2.5} className={classes.icon} />}
        <span className={classes.titleText}>{event.title}</span>
      </span>
      <span className={classes.meta}>
        {CHANNEL_LABELS[channel]} · {dayjs(event.start).format('HH:mm')}
      </span>
    </div>
  );
}

/** Drafts are outlined instead of filled: the package paints the box from `--event-bg` */
export function renderPostEvent(event: ScheduleEventData, props: RootProps) {
  const isDraft = getPayload(event).status === 'draft';
  const style = isDraft
    ? {
        ...(props.style as CSSProperties),
        '--event-bg': 'transparent',
        '--event-hover': 'var(--mantine-color-default-hover)',
      }
    : props.style;

  return (
    <UnstyledButton
      {...props}
      className={isDraft ? `${props.className} ${classes.draft}` : props.className}
      style={style}
      aria-label={getAccessibleName(event)}
    />
  );
}

export function renderAgendaPost(event: ScheduleEventData, props: RootProps) {
  const { channel, status } = getPayload(event);

  return (
    <UnstyledButton {...props} aria-label={getAccessibleName(event)}>
      <Group justify="space-between" wrap="nowrap" gap="sm" className={classes.agendaRow}>
        {props.children}
        <Text size="xs" className={classes.agendaMeta}>
          {CHANNEL_LABELS[channel]} · {STATUS_LABELS[status]}
        </Text>
      </Group>
    </UnstyledButton>
  );
}

import {
  Button,
  Group,
  Input,
  SegmentedControl,
  Select,
  Stack,
  TextInput,
  useModalCloseGuard,
} from '@mantine/core';
import { MaskedDateInput } from '@mantine/dates';
import { isNotEmpty, useForm } from '@mantine/form';
import { CHANNELS, STATUSES } from './channels';
import type { PostFormValues } from './types';

interface PostFormProps {
  initialValues: PostFormValues;
  isNew: boolean;
  /** Published posts keep their date */
  dateLocked: boolean;
  /** Newsletter issues always have a date, other drafts can stay unscheduled */
  dateRequired: boolean;
  onSubmit: (values: PostFormValues) => void;
}

export function PostForm({
  initialValues,
  isNew,
  dateLocked,
  dateRequired,
  onSubmit,
}: PostFormProps) {
  const closeModal = useModalCloseGuard();
  const form = useForm<PostFormValues>({
    name: 'content-post',
    initialValues,
    validate: {
      title: isNotEmpty('Enter a title'),
      channel: isNotEmpty('Pick a channel'),
      date: (value, values) => {
        if (value) {
          return null;
        }
        if (dateRequired) {
          return 'Pick a date';
        }
        return values.status === 'draft' ? null : 'Pick a date, or save the post as a draft';
      },
    },
  });

  const dateDescription = dateLocked
    ? 'Published posts cannot be moved'
    : dateRequired
      ? undefined
      : 'Leave empty to keep the draft unscheduled';

  return (
    <form onSubmit={form.onSubmit((values) => onSubmit({ ...values, title: values.title.trim() }))}>
      <Stack>
        <TextInput
          label="Title"
          placeholder="Title"
          withAsterisk
          data-autofocus
          {...form.getInputProps('title')}
        />
        <Select
          label="Channel"
          placeholder="Pick a channel"
          withAsterisk
          data={CHANNELS.map(({ value, label }) => ({ value, label }))}
          allowDeselect={false}
          {...form.getInputProps('channel')}
        />
        <MaskedDateInput
          label="Date and time"
          withTime
          clearable={!dateRequired && !dateLocked}
          disabled={dateLocked}
          withAsterisk={dateRequired}
          description={dateDescription}
          dayInputLabel="Day"
          monthInputLabel="Month"
          yearInputLabel="Year"
          hoursInputLabel="Hours"
          minutesInputLabel="Minutes"
          {...form.getInputProps('date')}
        />
        <Input.Wrapper label="Status" withBlockChildren>
          <SegmentedControl
            fullWidth
            data={STATUSES}
            {...form.getInputProps('status', { withError: false })}
          />
        </Input.Wrapper>
        <Group justify="flex-end">
          <Button variant="default" onClick={closeModal}>
            Cancel
          </Button>
          <Button type="submit">{isNew ? 'Create post' : 'Save changes'}</Button>
        </Group>
      </Stack>
    </form>
  );
}

